import type { WasmHashContext } from './types';

export type Scheme = {
  /** Hashes the current context. */
  create: (ctx: WasmHashContext) => Promise<string>;
  /** Checks if the input hash matches the create function of the scheme. */
  verify: (payload: string, ctx: WasmHashContext) => Promise<boolean>;
};

const sha256Hex = async (input: string): Promise<string> => {
  const digest = await crypto.subtle.digest('SHA-256', new TextEncoder().encode(input));
  return Array.from(new Uint8Array(digest), (b) => b.toString(16).padStart(2, '0')).join('');
};

const V1_PAYLOAD_LENGTH = 16;

const v1: Scheme = {
  create: async ({ userId }) =>
    (await sha256Hex(`wasm-hash-v1:${userId}`)).slice(0, V1_PAYLOAD_LENGTH),
  verify: async (payload, ctx) => payload === (await v1.create(ctx)),
};

export const SCHEME_ID_LENGTH = 2;

/**
 * Accepted schemes. Obfuscated by a hex-looking identifier.
 */
export const SCHEMES: ReadonlyMap<string, Scheme> = new Map([['3f', v1]]);

export const CURRENT_SCHEME_ID = '3f';
